from typesystem.tokenize.tokenize_json import _TokenizingJSONObject
from typesystem.tokenize.tokens import ScalarToken


def _scan_once(content):
    """Minimal value scanner that mirrors the real scan_once contract."""

    def scan_once(s, idx):
        start = idx
        while idx < len(s) and s[idx].isdigit():
            idx += 1
        if idx == start:
            raise StopIteration(idx)
        return ScalarToken(int(s[start:idx]), start, idx, content), idx

    return scan_once


def _parse(content, start, memo=None, strict=True):
    if memo is None:
