import pytest

from typesystem.base import ParseError, ValidationError
from typesystem.fields import Integer, String
from typesystem.schemas import Schema
from typesystem.tokenize.tokenize_json import validate_json


def _value_and_errors(result):
    if isinstance(result, tuple):
        assert len(result) == 2
        value, errors = result
        return value, errors
    return result, []


def _error_messages(error):
    messages = getattr(error, "messages", None)
    if callable(messages):
        messages = messages()
    return messages


def test_validate_json_with_field_and_string_content():
    result = validate_json('"hello"', validator=String())

    value, errors = _value_and_errors(result)

    assert value == "hello"
    assert not errors


def test_validate_json_with_field_and_bytes_content():
    result = validate_json(b"123", validator=Integer())

    value, errors = _value_and_errors(result)

    assert value == 123
    assert not errors


def test_validate_json_with_schema():
    class Movie(Schema):
        title = String(max_length=100)
        release_year = Integer(minimum=0)

    result = validate_json(
        '{"title": "Jaws", "release_year": 1975}', validator=Movie
    )

    value, errors = _value_and_errors(result)

    assert not errors
    if isinstance(value, dict):
        assert value == {"title": "Jaws", "release_year": 1975}
    elif hasattr(value, "keys"):
        assert {key: value[key] for key in value.keys()} == {
            "title": "Jaws",
            "release_year": 1975,
        }
    else:
        assert value.title == "Jaws"
        assert value.release_year == 1975


def test_validate_json_with_invalid_field_value():
    try:
        result = validate_json('"not-an-integer"', validator=Integer())
    except ValidationError as error:
        assert _error_messages(error)
    else:
        value, errors = _value_and_errors(result)
        assert value is None
        assert errors


def test_validate_json_with_invalid_json_content():
    with pytest.raises((ParseError, ValidationError)):
        validate_json("{invalid json", validator=String())
